fetch("http://localhost:4000/api/public/categories").then(function(t){return t.json()}).then(function(t){var e=t.categories||[];document.querySelectorAll("#live-category-list [data-category-name]").forEach(function(t){var o=t.getAttribute("data-category-name").trim().toLowerCase(),r=e.filter(function(t){return t.name.trim().toLowerCase()===o})[0];if(r){var a="products.html?category="+encodeURIComponent(r.slug);t.querySelectorAll("a").forEach(function(t){t.setAttribute("href",a)})}})}).catch(function(){});